package com.justenoughmods.achievementguide.integration.battlearmor;
import com.github.L_Ender.cataclysm.init.ModEffect;import java.util.*;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.damagesource.DamageSource;import net.minecraft.world.effect.MobEffectInstance;import net.minecraft.world.entity.*;import net.minecraft.world.item.ItemStack;import net.minecraftforge.event.entity.living.*;
public final class WorldBattleArmorQuestDamage {
 public static final class Hit {public final ServerPlayer actor;public final DamageSource source;public final float health;public final ItemStack legs;public boolean dodge,damage,brandBaseline;public LivingEntity branded;public MobEffectInstance oldBrand,newBrand;public Hit(ServerPlayer actor,DamageSource source){this.actor=actor;this.source=source;health=actor.getHealth();legs=actor.getItemBySlot(EquipmentSlot.LEGS).copy();}}
 public record Scope(LivingEntity target,Hit hit){}
 private static final class Scopes {final ArrayDeque<Scope> rows=new ArrayDeque<>();int overflow;}
 private static final ThreadLocal<Scopes> SCOPES=ThreadLocal.withInitial(Scopes::new);
 public static void scopeBegin(LivingEntity target,DamageSource source,float amount){if(!(target.level() instanceof net.minecraft.server.level.ServerLevel))return;var calls=SCOPES.get();if(calls.overflow>0||calls.rows.size()>=16){calls.overflow++;return;}calls.rows.push(new Scope(target,begin(target,source,amount)));}
 public static void scopeEnd(LivingEntity target,boolean accepted){if(!(target.level() instanceof net.minecraft.server.level.ServerLevel))return;var calls=SCOPES.get();if(calls.overflow>0){calls.overflow--;return;}var frame=calls.rows.poll();if(calls.rows.isEmpty())SCOPES.remove();if(frame!=null)end(frame.hit(),frame.target()==target&&accepted);}
 public record Dodge(Hit hit,boolean before,boolean eligible,boolean committed){}
 private static final ThreadLocal<ArrayDeque<Hit>> HITS=ThreadLocal.withInitial(ArrayDeque::new);private static final Map<LivingAttackEvent,Dodge> DODGES=new IdentityHashMap<>();
 public static Hit begin(LivingEntity entity,DamageSource source,float amount){var actor=WorldBattleArmorQuestProof.real(entity);if(actor==null||amount<=0||HITS.get().size()>=16)return null;var hit=new Hit(actor,source);HITS.get().push(hit);return hit;}
 public static Hit current(LivingEntity actor,DamageSource source){for(var hit:HITS.get())if(hit.actor==actor&&hit.source==source)return hit;return null;}
 public static void dodgeBefore(LivingAttackEvent event){var hit=current(event.getEntity(),event.getSource());if(hit!=null&&DODGES.size()<256)DODGES.put(event,new Dodge(hit,event.isCanceled(),event.getAmount()>0&&!event.getEntity().hasEffect(ModEffect.EFFECTGHOST_FORM.get())&&WorldBattleArmorQuestProof.smith(hit.actor,EquipmentSlot.LEGS,"cursium","cursium_leggings"),false));}
 public static void dodgeNative(LivingAttackEvent event,boolean canceledBefore){var r=DODGES.get(event);if(r!=null&&r.eligible&&!r.before&&!canceledBefore&&event.isCanceled())DODGES.put(event,new Dodge(r.hit,r.before,r.eligible,true));}
 public static void dodgeAfter(LivingAttackEvent event){if(!(event.getEntity().level() instanceof net.minecraft.server.level.ServerLevel))return;var receipt=DODGES.get(event);if(receipt!=null&&(!receipt.eligible||!receipt.committed||receipt.before||!event.isCanceled()))DODGES.remove(event);}
 public static void brandBefore(LivingDamageEvent event){var hit=current(event.getEntity(),event.getSource());if(hit!=null&&event.getSource().getEntity() instanceof LivingEntity attacker){var old=attacker.getEffect(ModEffect.EFFECTBLAZING_BRAND.get());hit.oldBrand=old==null?null:new MobEffectInstance(old);hit.brandBaseline=true;}}
 public static void brand(LivingDamageEvent event,LivingEntity target,MobEffectInstance effect,MobEffectInstance before,boolean accepted){var hit=current(event.getEntity(),event.getSource());if(hit==null||!accepted||effect.getEffect()!=ModEffect.EFFECTBLAZING_BRAND.get()||target==hit.actor||!target.isAlive()||!WorldBattleArmorQuestProof.smith(hit.actor,EquipmentSlot.LEGS,"ignitium","ignitium_leggings"))return;if(hit.brandBaseline)before=hit.oldBrand;var after=target.getEffect(effect.getEffect());if(WorldBattleArmorQuestProof.useful(before,after)){hit.branded=target;hit.oldBrand=before;hit.newBrand=new MobEffectInstance(after);}}
 public static void posted(net.minecraftforge.eventbus.api.Event event){if(event instanceof net.minecraftforge.event.entity.living.LivingEvent living&&!(living.getEntity().level() instanceof net.minecraft.server.level.ServerLevel))return;if(event instanceof LivingAttackEvent attack){var receipt=DODGES.remove(attack);if(receipt!=null&&receipt.eligible&&receipt.committed&&!receipt.before&&attack.isCanceled()&&WorldBattleArmorQuestProof.same(receipt.hit.legs,receipt.hit.actor.getItemBySlot(EquipmentSlot.LEGS)))receipt.hit.dodge=true;}if(event instanceof LivingDamageEvent damage){var hit=current(damage.getEntity(),damage.getSource());if(hit!=null&&!damage.isCanceled()&&damage.getAmount()>0)hit.damage=true;}}
 public static void end(Hit hit,boolean accepted){if(hit==null)return;var q=HITS.get();q.removeFirstOccurrence(hit);if(q.isEmpty())HITS.remove();if(WorldBattleArmorQuestProof.real(hit.actor)==null||!WorldBattleArmorQuestProof.same(hit.legs,hit.actor.getItemBySlot(EquipmentSlot.LEGS)))return;if(hit.dodge&&!accepted&&hit.actor.getHealth()==hit.health&&WorldBattleArmorQuestProof.smith(hit.actor,EquipmentSlot.LEGS,"cursium","cursium_leggings"))WorldBattleArmorQuestProof.emit(hit.actor,"v3_combat_cursium");if(hit.damage&&accepted&&hit.actor.getHealth()<hit.health&&hit.branded!=null&&hit.branded.isAlive()&&WorldBattleArmorQuestProof.useful(hit.oldBrand,hit.branded.getEffect(ModEffect.EFFECTBLAZING_BRAND.get()))&&WorldBattleArmorQuestProof.smith(hit.actor,EquipmentSlot.LEGS,"ignitium","ignitium_leggings"))WorldBattleArmorQuestProof.emit(hit.actor,"v3_combat_forged_armor");}
 public static void clear(){HITS.remove();SCOPES.remove();DODGES.clear();}
}
